-- Verify milk balance view matches authoritative remaining_ml.
do $$
declare v_mismatch int;
begin
  select count(*) into v_mismatch
  from public.milk_items mi
  join public.milk_item_balances mb on mb.milk_item_id=mi.id
  where mi.family_id='c5cf40f9-7228-ccd9-9166-7b9799b407a8'::uuid and mi.deleted_at is null
    and abs(coalesce(mi.remaining_ml,0)-coalesce(mb.remaining_ml,0)) > 0.001;
  if v_mismatch <> 0 then
    raise exception 'V15.0.76 milk balance mismatch rows: %', v_mismatch;
  end if;
end $$;

